Lemma ro_cells_rheap_pres : forall LB SP m m' A cs,
  rheap_pres LB SP m m' -> ro_cells usegs m A cs -> rclient_range LB SP A (Z.of_nat (cells_size cs)) -> ro_cells usegs m' A cs.
Proof.
  intros LB SP m m' A cs HP [Hwf HB] HR. split; [exact Hwf|].
  eapply rheap_pres_bytes_at; eauto. rewrite cells_bytes_length by assumption. exact HR.
Qed.


Definition P_ALLOCATE_RET1 : Z := 0x2e2e8.   (* [comment removed for export] *)
Definition DEALLOCATE_STACK : Z := RFREE_STACK.        (* [comment removed for export] *)
Definition ALLOCIMPL_DESTROY_STACK : Z := RFREE_STACK.  (* [comment removed for export] *)
Definition P_ALLOCIMPL_DESTROY_RET1 : Z := 0x2e2a0.
Definition ALLOCATE_STACK : Z := 64 + ROPNEW_STACK.

(* [comment removed for export] *)
Lemma nullbase_xor_pos : forall b s, 0 < b -> 0 < s -> Z.lxor (Z.b2z (0 <? b)) (Z.b2z (s <? 1)) = 1.
Proof.
  intros b s Hb Hs. destruct (Z.ltb_spec 0 b); destruct (Z.ltb_spec s 1); cbn; first [reflexivity | exfalso; lia].
Qed.

(* [comment removed for export] *)
Definition P_UB_ATD_CONFIG : Z := 0x2d278.
Definition P_UB_ATD_SCHED  : Z := 0x2fc18.
Definition P_UB_ATD_SSVC   : Z := 0x39048.
Definition P_UB_ATD_REG    : Z := 0x2ea74.
Definition atd_entry_ok (E : Z) : Prop := E = P_UB_ATD_CONFIG \/ E = P_UB_ATD_SCHED \/ E = P_UB_ATD_SSVC \/ E = P_UB_ATD_REG.
Definition atd_size (E : Z) : Z := if E =? P_UB_ATD_CONFIG then SZ_CFG else if E =? P_UB_ATD_SCHED then SZ_SCH else SZ_SSVC.
(* [comment removed for export] *)
Definition atd_ret (E : Z) : Z := if E =? P_UB_ATD_CONFIG then E + 52 else if E =? P_UB_ATD_SCHED then E + 48 else E + 44.
Definition ATD_STACK : Z := 16 + RFREE_STACK.           (* [comment removed for export] *)
Definition DOBJ_STACK : Z := 32 + ATD_STACK.            (* [comment removed for export] *)
Definition DALL_STACK : Z := 16 + DOBJ_STACK.           (* [comment removed for export] *)

(* [comment removed for export] *)
Definition dobj_entry_ok (E : Z) : Prop := E = P_DEALLOC_OBJ_CONFIG \/ E = P_DEALLOC_OBJ_SCHED \/ E = P_DEALLOC_OBJ_SSVC.
Definition dobj_size (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then SZ_CFG else if E =? P_DEALLOC_OBJ_SCHED then SZ_SCH else SZ_SSVC.
Definition dobj_vp (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then VP_CONFIG_SVC else if E =? P_DEALLOC_OBJ_SCHED then VP_SCHED else VP_SSVC.
Definition dobj_dtor (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then P_NONCOPYABLE_DTOR else if E =? P_DEALLOC_OBJ_SCHED then P_SCHED_DTOR else P_SSVC_DTOR.
Definition dobj_atd (E : Z) : Z := if E =? P_DEALLOC_OBJ_CONFIG then P_UB_ATD_CONFIG else if E =? P_DEALLOC_OBJ_SCHED then P_UB_ATD_SCHED else P_UB_ATD_SSVC.
(* [comment removed for export] *)
Definition dobj_epi_ok (pcC : Z) : Prop :=
  pcC = P_DEALLOC_OBJ_CONFIG + 68 \/ pcC = P_DEALLOC_OBJ_SCHED + 68 \/ pcC = P_DEALLOC_OBJ_SSVC + 68.
Lemma dobj_epi_of_entry : forall E, dobj_entry_ok E -> dobj_epi_ok (E + 68).
Proof. intros E [-> |[-> | ->]]; unfold dobj_epi_ok; auto. Qed.
Lemma dobj_atd_ok : forall E, dobj_entry_ok E -> atd_entry_ok (dobj_atd E).
Proof. intros E [-> |[-> | ->]]; unfold atd_entry_ok, dobj_atd; cbn; auto. Qed.
Lemma dobj_atd_size : forall E, dobj_entry_ok E -> atd_size (dobj_atd E) = dobj_size E.
Proof. intros E [-> |[-> | ->]]; reflexivity. Qed.


