Definition deallocate_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (p : bptr) (A size lo B : Z) (errv : word) (j7 : list byte),
      a1 = Z_to_bv 64 A -> a2 = Z_to_bv 64 size -> a3 = Z_to_bv 64 8 ->
      0 <= size -> In (p, A, size + 15) LB ->
      rw_cells usegs m (A + size) (CookieCells j7) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DEALLOCATE_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (free_sr_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB p lo B errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) fc None m (seg_rom usegs)) mo).

  Lemma deallocate_spec : deallocate_stmt.
  Proof.
    intros until j7. intros -> -> -> S0 IN CK HP KREL AUX SPB ST CEIL LO ERR MI TP.
    unfold DEALLOCATE_STACK in LO. hcb.
    pose proof (hh_blocks H HH _ _ _ _ HP IN) as (R1 & R2 & R3 & R4 & R5). cbn in R1, R2, R3, R4, R5.
    eapply (hh_evt_then H HH); [exact KREL| eapply dealloc_seg; try eassumption; lia|].
    intros ms1 PO. destruct PO as (b0 & b2 & b3 & b4 & b5 & b6 & b7 & ->).
    pose proof (hh_opdel2 H HH) as DEL. unfold opdel2_sr_stmt, free_sr_stmt_at in DEL.
    eapply DEL; try eassumption; try reflexivity; lia.
  Qed.


  Lemma xpres_free : forall s LB m0 p A n SP X m m',
    hs_RHEAP H s LB m0 -> In (p, A, n) LB ->
    rheap_pres (hs_lb_remove H p LB) SP m m' ->
    (forall a, A <= a < A + n -> rin_ivs X a) ->
    xpres LB SP X m m'.
  Proof.
    intros s LB m0 p A n SP X m m' HP IN PRES HX q Hq [HC NX]. apply PRES; [exact Hq|].
    destruct HC as [K|[K|(b & Hb & K)]]; [left; exact K| right; left; exact K| right; right].
    exists b. split; [| exact K].
    apply (hh_lb_remove_keep H HH); [exact (hh_nodup H HH _ _ _ HP)| exact Hb|].
    intros E. assert (b = (p, A, n)) by (eapply nodup_blk_eq; [exact (hh_nodup H HH _ _ _ HP)| exact Hb| exact IN| exact E]).
    subst b. cbn in K. apply NX. apply HX. exact K.
  Qed.

  Definition adestroy_seg_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (a lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 a) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp).

  Lemma adestroy_seg : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (a lo : Z) (junk : list byte),
    rw_cells usegs m a [C8 (wz VP_ALLOCIMPL); CB 8 junk] -> XStatics m ->
    stk usegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
    (a + 16 <= lo \/ bv_unsigned sp <= a) -> a + 16 <= 2^64 ->
    mem_inv usegs m ->
    evt usegs (adestroy_seg_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc a lo m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 a) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_ALLOCIMPL_DESTROY) fc None m (seg_rom usegs)).
  Proof.
    ltac2:(KReplay.run [|constr:(@stdpp.bitvector.definitions.bv); constr:(@Corelib.Numbers.BinNums.Npos); constr:(@Corelib.Numbers.BinNums.xO); constr:(@Corelib.Numbers.BinNums.xH); constr:(@LinuxProcessSemantics.Riscv.Prelude.bvmap); constr:(@Corelib.Numbers.BinNums.xI); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.RMalloc_iface_stmt.mem); constr:(@Corelib.Numbers.BinNums.Z); constr:(@Corelib.Init.Datatypes.list); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Step.rw_cells); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.USegs.usegs); constr:(@Corelib.Init.Datatypes.cons); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Cells.cell); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Cells.C8); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.TacX.wz); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XRep.VP_ALLOCIMPL); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Cells.CB); constr:(@Corelib.Init.Datatypes.S); constr:(@Corelib.Init.Datatypes.O); constr:(@Corelib.Init.Datatypes.nil); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XRep.XStatics); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Frame.stk); constr:(@stdpp.bitvector.definitions.bv_unsigned); constr:(@Stdlib.ZArith.BinInt.Z.le); constr:(@Stdlib.ZArith.BinInt.Z.add); constr:(@Corelib.Numbers.BinNums.Zpos); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.HeapCeil.hceil); constr:(HCEIL); constr:(@Corelib.Init.Logic.or); constr:(@Stdlib.ZArith.BinInt.Z.pow); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Mem.mem_inv); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Ub.XA_alloc.HCW.XS_allocimpl_vt); constr:(@stdpp.bitvector.definitions.Z_to_bv); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Lib.Step.rw_cells_bound); constr:(@Corelib.Init.Logic.and); constr:(@Corelib.Numbers.BinNums.Z0); constr:(@Stdlib.ZArith.BinInt.Z.of_nat); constr:(@OSSVerify.Proofs.boost_beast.h