  (* [comment removed for export] *)
  Definition atd_segA_post (sp gp tp t0 t1 t2 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E pobj allocb lo : Z) (ra : word) (m : mem) : machine_state -> Prop :=
    fun ms' => exists m' junk,
      ms' = MS (mkR (Z_to_bv 64 (atd_ret E)) (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1
                    (Z_to_bv 64 allocb) (Z_to_bv 64 pobj) (Z_to_bv 64 (atd_size E)) (Z_to_bv 64 8) (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_ALLOCIMPL_DEALLOCATE) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -16)
      /\ rw_cells usegs m' (bv_unsigned sp + -16) [CB 8 junk; C8 ra].
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.

  Lemma atd_segA : forall (E : Z), atd_entry_ok E ->
    forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (AT pobj allocb lo : Z),
    ro_cells usegs m AT [C8 (wz allocb)] -> ro_cells usegs m allocb [C8 (wz VP_ALLOCIMPL)] -> XStatics m ->
    stk usegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
    (AT + 8 <= lo \/ bv_unsigned sp <= AT) -> (allocb + 8 <= lo \/ bv_unsigned sp <= allocb) ->
    0 < allocb -> allocb mod 8 = 0 ->
