    stk usegs m lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp ->
    mem_inv usegs m ->
    evt usegs (atd_segC_post ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc lo m)
