  Definition dobj_segA_post (sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E pobj allocb lo : Z) (ra s0 s1 : word) (m : mem) : machine_state -> Prop :=
    fun ms' => exists m' junk,
      ms' = MS (mkR (Z_to_bv 64 (E + 52)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
                    (Z_to_bv 64 pobj) s1 (Z_to_bv 64 pobj) (Z_to_bv 64 (dobj_dtor E)) a2 a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 (dobj_dtor E)) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -32)
      /\ rw_cells usegs m' (bv_unsigned sp + -32) [CB 8 junk; C8 (Z_to_bv 64 allocb); C8 s0; C8 ra].

  Lemma dobj_segA : forall (E : Z), dobj_entry_ok E ->
    forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (AT pobj allocb lo : Z),
    ro_cells usegs m AT [C8 (wz allocb)] -> ro_cells usegs m pobj [C8 (wz (dobj_vp E))] -> XStatics m ->
    stk usegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
    (AT + 8 <= lo \/ bv_unsigned sp <= AT) -> (pobj + 8 <= lo \/ bv_unsigned sp <= pobj) ->
    0 < pobj -> pobj mod 8 = 0 ->                                                   (* [comment removed for export] *)
    mem_inv usegs m ->
    evt usegs (dobj_segA_post sp gp tp t0 t1 t2 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc E pobj allocb lo ra s0 s1 m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 pobj) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 E) fc None m (seg_rom usegs)).
