  Definition dobj_segB_post (sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E pobj : Z) (m : mem) : machine_state -> Prop :=
    fun ms' =>
      ms' = MS (mkR (Z_to_bv 64 (E + 68)) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 s0 s1
                    (Z_to_bv 64 (bv_unsigned sp + -24)) (Z_to_bv 64 pobj) (Z_to_bv 64 1) a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
