  (* [comment removed for export] *)
  Definition dobj_segC_post (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (lo : Z) (m : mem) : machine_state -> Prop :=
    fun ms' =>
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (ret_pc ra) fc None m (seg_rom usegs)
      /\ munch [] m m /\ wmono usegs m m /\ mem_inv usegs m
      /\ stk usegs m lo (bv_unsigned sp).

  Lemma dobj_segC : forall (pcC : Z), dobj_epi_ok pcC ->
    forall (rax : word) sp gp tp t0 t1 t2 (s0x : word) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra s0 ab : word)
      (F : bvmap 5 word) fc (m : mem) (lo : Z) (junk : list byte),
    rw_cells usegs m (bv_unsigned sp + -32) [CB 8 junk; C8 ab; C8 s0; C8 ra] ->
    stk usegs m lo (bv_unsigned sp + -32) -> lo + 32 <= bv_unsigned sp ->
    mem_inv usegs m ->
    evt usegs (dobj_segC_post ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc lo m)
      (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 s0x s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
