  (* [comment removed for export] *)
  Definition dobj_tail_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (p : bptr) (lo B : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' (hs_lb_remove H p LB) m'
      /\ rheap_pres (hs_lb_remove H p LB) (bv_unsigned sp - 32) m m'.

  Definition dobj_tail_stmt (E : Z) : Prop :=
    forall (rax sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 ra s0 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (p : bptr) (pobj allocb lo B : Z) (errv : word) (junk j7 : list byte),
      In (p, pobj, dobj_size E + 15) LB -> rw_cells usegs m (pobj + dobj_size E) (CookieCells j7) ->
      ro_cells usegs m allocb [C8 (wz VP_ALLOCIMPL)] -> XStatics m ->
      (allocb + 8 <= lo \/ bv_unsigned sp <= allocb) -> 0 < allocb -> allocb mod 8 = 0 ->          (* [comment removed for export] *)
      rw_cells usegs m (bv_unsigned sp + -32) [CB 8 junk; C8 (Z_to_bv 64 allocb); C8 s0; C8 ra] ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk usegs m lo (bv_unsigned sp + -32) -> hceil <= lo -> lo <= bv_unsigned sp - DOBJ_STACK ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (dobj_tail_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB p lo B errv m mo)
        (mkCfg (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (Z_to_bv 64 pobj) s1
                        a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 (E + 52)) fc None m (seg_rom usegs)) mo).

  Lemma dobj_tail_spec : forall E, dobj_entry_ok E -> dobj_tail_stmt E.
