(* [comment removed for export] *)
  Definition dall_entry_ok (E' : Z) : Prop := E' = P_DESTROY_ALLOC_CONFIG \/ E' = P_DESTROY_ALLOC_SCHED \/ E' = P_DESTROY_ALLOC_SSVC.
  Definition dall_target (E' : Z) : Z :=
    if E' =? P_DESTROY_ALLOC_CONFIG then P_DEALLOC_OBJ_CONFIG else if E' =? P_DESTROY_ALLOC_SCHED then P_DEALLOC_OBJ_SCHED else P_DEALLOC_OBJ_SSVC.

  (* [comment removed for export] *)
  Definition dall_segA_post (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (E' svc allocb lo : Z) (ra : word) (m : mem) : machine_state -> Prop :=
    fun ms' => exists (a2x : word) m',
      ms' = MS (mkR (Z_to_bv 64 (E' + 56)) (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 s0 s1
                    (Z_to_bv 64 (bv_unsigned sp + -16)) (Z_to_bv 64 svc) a2x a3 a4 a5 a6 a7
                    s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 (dall_target E')) fc None m' (seg_rom usegs)
      /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
      /\ stk usegs m' lo (bv_unsigned sp + -16)
      /\ rw_cells usegs m' (bv_unsigned sp + -16) [C8 (Z_to_bv 64 allocb); C8 ra].

  Lemma dall_segA : forall (E' : Z), dall_entry_ok E' ->
    forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (svc ioc allocb lo : Z),
    ro_cells usegs m (svc + O_SVC_OWNER) [C8 (wz ioc)] -> ro_cells usegs m ioc [C8 (wz allocb)] ->
    stk usegs m lo (bv_unsigned sp) -> lo + 16 <= bv_unsigned sp -> hceil <= lo ->
    (svc + SZ_SVC <= lo \/ bv_unsigned sp <= svc) -> (ioc + 8 <= lo \/ bv_unsigned sp <= ioc) -> 0 <= svc ->
    0 < svc -> svc mod 8 = 0 -> 0 < ioc -> ioc mod 8 = 0 ->                          (* [comment removed for export] *)
    mem_inv usegs m ->
    evt usegs (dall_segA_post sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc E' svc allocb lo ra m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 svc) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 E') fc None m (seg_rom usegs)).
